ALTER PROCEDURE [dbo].[SavePageTokens]
(
	@PageTokens dbo.PageTokenType READONLY
) AS
BEGIN--PROCEDURE
	SET NOCOUNT ON;

	BEGIN TRANSACTION

	DELETE FROM
		[dbo].[PageToken]
	WHERE
		[PageId] IN (SELECT PageId FROM @PageTokens)

	INSERT INTO [dbo].[PageToken]
	(
		[PageId],
		[Token],
		[DoubleMetaphone],
		[Weight]
	)
	SELECT
		[PageId],
		[Token],
		[DoubleMetaphone],
		[Weight]
	FROM
		@PageTokens

	COMMIT TRANSACTION

END--PROCEDURE


GO
