ALTER PROCEDURE [dbo].[UpdatePageProcessingInstructions]
(
	@PageId Int,
	@Instructions nVarChar(MAX)
) AS
BEGIN--PROCEDURE
	SET NOCOUNT ON;

	BEGIN TRANSACTION

	DELETE FROM
		PageProcessingInstruction
	WHERE
		PageId = @PageId

	INSERT INTO PageProcessingInstruction
	(
		PageId,
		Instruction
	)
	SELECT
		@PageId,
		SP.[value]
	FROM
		STRING_SPLIT(@Instructions ,',') as SP
	WHERE
		IsNull(SP.[value], '') <> ''

	COMMIT TRANSACTION

END--PROCEDURE

