ALTER PROCEDURE [dbo].[UpdatePageReferences]
(
	@PageId as int,
	@ReferencesPageNavigations as nvarchar (max)
) AS
BEGIN--PROCEDURE
	SET NOCOUNT ON;

	BEGIN TRANSACTION

	DELETE FROM
		PageReference
	WHERE
		PageId = @PageId

	INSERT INTO PageReference
	(
		PageId,
		ReferencesPageName,
		ReferencesPageNavigation,
		ReferencesPageId
	)
	SELECT DISTINCT
		@PageId,
		TRIM(SUBSTRING(Value, CHARINDEX(':', Value) + 1, LEN(Value) - (CHARINDEX(':', Value)))) as [Name],
		TRIM(SUBSTRING(Value, 1, CHARINDEX(':', Value) - 1)) as Navigation,
		P.Id
	FROM
		STRING_SPLIT(@ReferencesPageNavigations, CHAR(10)) as Split
	LEFT OUTER JOIN [Page] as P
		ON P.Navigation = TRIM(SUBSTRING(Value, 1, CHARINDEX(':', Value) - 1))
	WHERE
		Split.[value] <> ''

	UPDATE
		PR
	SET
		ReferencesPageNavigation = P.Navigation
	FROM
		PageReference as PR
	INNER JOIN [Page] as P
		ON P.Id = PR.ReferencesPageId
	WHERE
		P.Id = @PageId

	COMMIT TRANSACTION

END--PROCEDURE

GO
