	[PageId],[Name],[Description],[Body],[Revision],[ModifiedByUserId],[ModifiedDate]
FROM #tmp_7a655d4850454789b76413ec08250f2a as S
WHERE NOT EXISTS (
	SELECT TOP 1 1 FROM  [dbo].[PageRevision] as T
	WHERE T.[PageId] = S.[PageId] AND T.[Revision] = S.[Revision]
)
