GO
UPDATE T SET 
T.[Weight] = S.[Weight],
T.[DoubleMetaphone] = S.[DoubleMetaphone]

FROM [dbo].[PageToken] as T
INNER JOIN #tmp_518d2ab9b3734d3eb7218936c91b2bd0 as S
ON T.[PageId] = S.[PageId] AND T.[Token] = S.[Token]
GO
INSERT INTO [dbo].[PageToken] (
	[PageId],[Token],[Weight],[DoubleMetaphone])
SELECT
	[PageId],[Token],[Weight],[DoubleMetaphone]
FROM #tmp_518d2ab9b3734d3eb7218936c91b2bd0 as S
WHERE NOT EXISTS (
	SELECT TOP 1 1 FROM  [dbo].[PageToken] as T
	WHERE T.[PageId] = S.[PageId] AND T.[Token] = S.[Token]
)
